entries[35294] = { ["name"] = "Rezept: Elixier der Schwächung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(365)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der Schwächung.\nElixier der Schwächung\nBenötigt Stufe 60\nBenutzen: Reduziert die Magiewiderstände der Ziele Eurer Zauber 1 hour lang um 30. Wächterelixier. (3 Sek. Abklingzeit)\nBenötigt Netherblüte , Manadistel , Magieerfüllte Phiole" }
