entries[35498] = { ["name"] = "Formel: Waffe - Todeskälte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (350)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass Schadenszauber und Nahkampftreffer gelegentlich zusätzlich Frostschaden verursachen und das Ziel verlangsamen. Erfordert einen Gegenstand der Stufe 60 oder höher.\nEine Nahkampfwaffe dauerhaft so verzaubern, sodass Schadenszauber und Nahkampftreffer gelegentlich zusätzlich Frostschaden verursachen und das Ziel verlangsamen. Erfordert einen Gegenstand der Stufe 60 oder höher.\n\nDer Verlangsamungseffekt ist bei Zielen der Stufe 73 oder höher unwirksam." }
entries[35499] = { ["name"] = "Ninja Grenade [PH]", ["text"] = "Benutzen: Fügt 450 to 750 Feuerschaden zu und betäubt Ziele 3 sec lang in einem Radius von 3 Metern. Jeglicher Schaden wird den Effekt abbrechen. Unzuverlässig gegen Ziele über Stufe 80. (1 Min Abklingzeit)" }
entries[35500] = { ["name"] = "Formel: Brust - Verteidigung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (360)\nBenötigt Offensive der Zerschmetterten Sonne\n- Wohlwollend\nBenutzen: Lehrt Euch, Brustrüstungen dauerhaft zu verzaubern, sodass sie die Verteidigungswertung um 16 erhöhen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Brustrüstung dauerhaft verzaubern, sodass die Verteidigungswertung um 16 erhöht wird. Benötigt einen Gegenstand der Stufe 35 oder höher." }
