entries[35716] = { ["name"] = "Fläschchen des reinen Todes aus Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht den durch Schatten-, Feuer- und Frostzauber verursachten Schaden 1 hour lang um bis zu 80. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
